import{_ as e,c as t,o as a,ae as n}from"./chunks/framework.Bw0Gm4PQ.js";const g=JSON.parse('{"title":"ENDING TAXPAYER SUBSIDIZATION OF BIASED MEDIA","description":"","frontmatter":{"title":"ENDING TAXPAYER SUBSIDIZATION OF BIASED MEDIA","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/05/ending-taxpayer-subsidization-of-biased-media/","publishDate":"2025-05-01T23:00:59-04:00"},"headers":[],"relativePath":"executive-orders/2025-05-02-ending-taxpayer-subsidization-of-biased-media.md","filePath":"executive-orders/2025-05-02-ending-taxpayer-subsidization-of-biased-media.md"}'),s={name:"executive-orders/2025-05-02-ending-taxpayer-subsidization-of-biased-media.md"};function o(r,i,d,l,p,c){return a(),t("div",null,i[0]||(i[0]=[n('<h1 id="ending-taxpayer-subsidization-of-biased-media" tabindex="-1">ENDING TAXPAYER SUBSIDIZATION OF BIASED MEDIA <a class="header-anchor" href="#ending-taxpayer-subsidization-of-biased-media" aria-label="Permalink to &quot;ENDING TAXPAYER SUBSIDIZATION OF BIASED MEDIA&quot;">​</a></h1><p>Published: Friday, May 2, 2025</p><ul><li><p><strong>Authority</strong>: The President orders actions based on constitutional powers and U.S. laws.</p></li><li><p><strong>Context</strong>: National Public Radio (NPR) and the Public Broadcasting Service (PBS) receive taxpayer funding via the Corporation for Public Broadcasting (CPB). The media landscape has evolved since the CPB was established in 1967, making government funding outdated and detrimental to perceived journalistic independence.</p></li><li><p><strong>Expectations</strong>: Taxpayer-funded public broadcasting should provide fair, accurate, unbiased, and nonpartisan news coverage. No media outlet is entitled to taxpayer subsidies.</p></li><li><p><strong>CPB Violations</strong>: The CPB is criticized for failing to maintain impartiality, as it subsidizes NPR and PBS, which do not present unbiased news.</p></li><li><p><strong>Funding Directives</strong>:</p><ul><li><p><strong>CPB Board</strong>:</p><ul><li>Must stop direct funding for NPR and PBS, cancelling existing funding where legally permissible.</li><li>Must prevent indirect funding through public stations and ensure grants do not support NPR or PBS by revising eligibility criteria by June 30, 2025.</li></ul></li><li><p><strong>Agency Heads</strong>:</p><ul><li>Required to identify and terminate any direct or indirect funding for NPR and PBS.</li><li>Must review existing grants and contracts with NPR and PBS for compliance and take necessary actions if noncompliance is found.</li></ul></li></ul></li><li><p><strong>Compliance Check</strong>: The Secretary of Health and Human Services will evaluate if NPR and PBS comply with anti-discrimination laws in employment. Corrective actions will be taken if noncompliance is found.</p></li><li><p><strong>Validity Clause</strong>: If any part of this order is deemed invalid, the rest will remain effective.</p></li><li><p><strong>Authority &amp; Implementation</strong>:</p><ul><li>This order does not limit existing legal authorities of departments or agencies.</li><li>It must be implemented in alignment with applicable laws and available appropriations.</li><li>No legal rights are created for enforcement against the U.S. or its entities.</li></ul></li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/05/ending-taxpayer-subsidization-of-biased-media/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/05/ending-taxpayer-subsidization-of-biased-media/</a></p>',4)]))}const f=e(s,[["render",o]]);export{g as __pageData,f as default};
